import{t as e}from"./framework~index~page~page~page~page~page~layout~page~page~page~page~page~page~page~page~pag~eztgd4df-BzIW9Sxt.js";import{t}from"./PageFrame-R-ar4DWr.js";var n=e(),r={title:`FAQ | Keith Lee Partnerships`,description:`Answers about restaurant visits, partnerships, editorial independence, disclosures, scheduling, and outcomes.`},i=[[`Can a restaurant pay for a positive review?`,`No. Commercial consideration does not purchase a favorable reaction or guarantee coverage. Editorial perspective and honest experience remain independent.`],[`What is the difference between an organic visit and a paid partnership?`,`An organic visit is independently chosen and not commissioned. A paid partnership is contractually scoped, disclosed, and reviewed for brand fit, usage rights, and deliverables.`],[`Does an inquiry guarantee a visit or collaboration?`,`No. Submitting an inquiry starts a fit review. Availability, conflicts, logistics, editorial boundaries, and operational readiness all affect the decision.`],[`How far in advance should we inquire?`,`Timing depends on scope. Speaking and restaurant campaigns commonly need several weeks; multi-market and destination programs typically need a longer planning runway.`],[`Should we share a budget?`,`Yes. A credible range helps the team assess fit and recommend an appropriate path without unnecessary back-and-forth.`],[`Can performance results be guaranteed?`,`No. Audience response, restaurant demand, sales, foot traffic, and press attention cannot be guaranteed. Any public outcomes must be documented and approved.`],[`How are sponsorships disclosed?`,`Paid, gifted, hosted, or otherwise material relationships should be labeled clearly in line with the final platform, contract, and legal requirements.`],[`What should restaurants prepare operationally?`,`Share capacity, service constraints, allergy practices, accessibility information, security considerations, and the team responsible for the activation.`],[`Can an agency submit for a client?`,`Yes. Identify the end client, your agency role, the decision-maker, approval process, and who controls the budget.`],[`How can we verify a booking request?`,`Use the official inquiry flow on this site. Do not send payment or confidential information to an unverified account claiming to represent Keith.`]];function a(){return(0,n.jsx)(t,{children:(0,n.jsxs)(`main`,{className:`inner-main`,children:[(0,n.jsx)(`section`,{className:`inner-hero faq-hero`,children:(0,n.jsxs)(`div`,{children:[(0,n.jsxs)(`p`,{className:`eyebrow`,children:[(0,n.jsx)(`span`,{}),` Frequently asked`]}),(0,n.jsx)(`h1`,{children:`Clarity before the first call.`}),(0,n.jsx)(`p`,{children:`Direct answers about access, independence, scheduling, disclosures, operational readiness, and what collaboration can realistically deliver.`})]})}),(0,n.jsxs)(`section`,{className:`faq-layout`,children:[(0,n.jsxs)(`aside`,{children:[(0,n.jsx)(`strong`,{children:`Still deciding?`}),(0,n.jsx)(`p`,{children:`Start with the engagement pathways, then use the structured inquiry when the opportunity is concrete.`}),(0,n.jsx)(`a`,{href:`/collaborations`,children:`Explore collaborations`}),(0,n.jsx)(`a`,{href:`/partner`,children:`Begin an inquiry`})]}),(0,n.jsx)(`div`,{className:`faq-list`,children:i.map(([e,t],r)=>(0,n.jsxs)(`details`,{open:r===0,children:[(0,n.jsxs)(`summary`,{children:[e,(0,n.jsx)(`span`,{children:`+`})]}),(0,n.jsx)(`p`,{children:t})]},e))})]})]})})}export{a as default,r as metadata};